<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{EWallet,FeeSetting,WalletTransaction}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
 class WalletController extends Controller { public function show(Request $r){return response()->json($r->user()->wallet()->with('transactions')->firstOrCreate(['user_id'=>$r->user()->id]));} public function topUp(Request $r){$d=$r->validate(['amount'=>'required|integer|min:1000']); $fee=FeeSetting::value('top_up_fee',1000); $wallet=DB::transaction(function()use($r,$d,$fee){$w=EWallet::where('user_id',$r->user()->id)->lockForUpdate()->firstOrCreate(['user_id'=>$r->user()->id],['balance'=>0]); $w->increment('balance',$d['amount']); WalletTransaction::create(['e_wallet_id'=>$w->id,'type'=>'TOP_UP','debit'=>0,'credit'=>$d['amount'],'amount'=>$d['amount'],'fee'=>$fee,'description'=>'Top up saldo','reference'=>'TOPUP-'.str()->upper(str()->random(10))]); return $w->fresh();}); return response()->json(['wallet'=>$wallet,'charged'=>$d['amount']+$fee,'fee'=>$fee]); } }
